import { pipeline } from 'node:stream/promises';
import { Transform } from 'node:stream';

export function createBatchProcessor(batchSize) {
  let buffer = [];
  return new Transform({
    objectMode: true,
    transform(chunk, encoding, callback) {
      buffer.push(chunk);
      if (buffer.length >= batchSize) {
        const batch = buffer;
        buffer = [];
        this.push(batch);
      }
      callback();
    },
    flush(callback) {
      if (buffer.length > 0) {
        this.push(buffer);
      }
      callback();
    }
  });
}

